// Authored exercises: original multi-part problems with a full correction, for the five priority classes.
// `w` is the weight of a part in a marking scheme; `ok()` recomputes the numbers quoted in the correction.
// Chapter ids: content/data/manifest.json. Levels: 1 routine, 2 standard, 3 demanding.
import { M, R } from './engine.js';

const near = (a, b, tol = 1e-9) => Math.abs(a - b) <= tol * Math.max(1, Math.abs(a), Math.abs(b));
const nd = (f, x) => (f(x + 1e-6) - f(x - 1e-6)) / 2e-6;

